insert into public.tips (id, unit_id, title_en, body_md, status) values
  ('9c8a1e7a-1493-5571-8ed6-618849217504', '59b48665-2d47-587e-b406-84d2800c4161', 'Quería que vinieras', 'When the wanting is in the past, the second verb moves into the past too: *quiero que vengas* becomes **quería que vinieras** — *I wanted you to come*.', 'draft'),
  ('e955f0b9-f8b0-5d65-9a69-423334218db4', '59b48665-2d47-587e-b406-84d2800c4161', 'Me pidió que', '**Me pidió que lo llamara** — *she asked me to call him*. The same form follows an order told later: **me dijo que esperara** — *he told me to wait*.', 'draft'),
  ('25d6923c-91de-5dbc-8d0d-f9169a29f8a7', '21206ba6-6522-5849-be52-419e7d6d1007', 'Aunque: a fact, or a maybe', '**Aunque llueve, vamos** — it''s raining, and we''re going. **Aunque llueva, vamos** — whether it rains or not. A fact takes the normal verb; a maybe takes the subjunctive.', 'draft'),
  ('867bb841-c3ee-5915-a39a-2a142147407f', '21206ba6-6522-5849-be52-419e7d6d1007', 'Igual, a pesar de', 'Porteños close the thought with **igual** — *anyway*: *aunque esté cansada, voy igual*. **A pesar de** takes a noun or an infinitive: *a pesar del frío*.', 'draft'),
  ('ad0af3c3-e6a3-532d-a35d-84c7f8160893', 'dd303fe0-52c5-5e61-97ae-1903616e625c', 'Llevo dos años', '**Llevo dos años viviendo acá** — *I''ve been living here for two years*. Where English says *have been …ing*, Spanish stays in the present: **hace dos años que vivo acá** says the same.', 'draft'),
  ('db3851d6-3b46-5dd4-bb1b-6ef931ec1c39', 'dd303fe0-52c5-5e61-97ae-1903616e625c', 'Sigo, dejé de, volví a', '**Sigo laburando ahí** — *I still work there*. **Dejé de fumar** — *I quit smoking*. **Volvió a llamar** — *he called again*.', 'draft'),
  ('1baca3ac-551e-5932-bf44-55602718f676', '518b71b2-b596-542b-9566-2ef65e7af724', 'Quería que, aunque', '**Quería que vinieras** puts the wish in the past, so the second verb follows it. **Aunque** takes the subjunctive only for a maybe: *aunque llueva*.', 'draft'),
  ('cca92f4b-c789-5d3b-95f1-85baa03da3d2', '518b71b2-b596-542b-9566-2ef65e7af724', 'Llevo, sigo', '**Llevo un rato esperando** — *I''ve been waiting a while*. **Sigo esperando** — *I''m still waiting*.', 'draft'),
  ('00cd9498-1215-5c48-afe6-17679fe9286b', 'c7b4cc13-41a1-57bf-b8f9-9c5a2ef4fb1b', 'Pasen, vengan', 'To more than one person, a command ends in **-en** for -ar verbs and in **-an** for the rest: **pasen**, **esperen**, **vengan**, **traigan**. A pronoun sticks to the end: **siéntense**.', 'draft'),
  ('01a808b3-a1c9-5477-ae3a-bbb29595b2ee', 'c7b4cc13-41a1-57bf-b8f9-9c5a2ef4fb1b', 'Están en su casa', 'A porteño host says **pasen, pasen** at the door, **pónganse cómodos**, and **no se preocupen** when you apologise for being late.', 'draft'),
  ('535227c6-093e-55ff-97bb-1fc13d684f30', 'e31d82b3-e9e2-52bc-bd88-e52c7b53a764', 'Como si', '**Como si** — *as if* — always takes the past subjunctive: **habla como si supiera todo**, **como si fuera fácil**. **Como si nada** — *as if nothing had happened*. **¡Ni que fuera tan difícil!** — *it''s not like it''s that hard!*', 'draft'),
  ('cf806c31-8f85-5040-8303-14a57a557a27', 'e31d82b3-e9e2-52bc-bd88-e52c7b53a764', 'Se hace el vivo', '**Hacerse el** + a describing word is *to act, to play*: **se hace el vivo** — *he acts all clever*; **se hizo el distraído** — *he pretended not to notice*.', 'draft'),
  ('95f52f58-d218-5e92-970e-b0e462cb47b8', 'b3d7d4fe-8ba0-58f9-8d0e-38b9aaf3707f', 'El que, la que', '**El que** — *the one that* — matches what it stands for: **el que quieras**, **la que está en la esquina**, **los que vinieron**, **las que prefieras**.', 'draft'),
  ('30fc7173-4d31-50b4-9bfa-84b45404bd59', 'b3d7d4fe-8ba0-58f9-8d0e-38b9aaf3707f', 'Donde', '**Donde** with no accent joins a place to the rest of the sentence: **el bar donde nos conocimos** — *the bar where we met*. The question keeps its accent: *¿dónde?*', 'draft'),
  ('02ccd3ab-67b7-5899-aaa7-64f6847cb270', '696d87b3-3675-5b84-ae2f-61e5be334c9a', 'Pasen, siéntense', 'For more than one person: **pasen**, **vengan**, **siéntense**, **no se preocupen**.', 'draft'),
  ('a8ab9b46-086f-55ce-98d9-cbf02a2d003b', '696d87b3-3675-5b84-ae2f-61e5be334c9a', 'Como si, el que', '**Como si** takes the past subjunctive: *como si supiera*. **El que, la que** — *the one that*: *la que prefieras*.', 'draft'),
  ('39ab066b-9188-56d2-9af6-ffa815e191bf', 'aaafb4dd-18af-5b10-be4f-33a46f2cba0e', 'Si hubiera sabido', 'For what didn''t happen: **si hubiera sabido, te hubiera avisado** — *if I''d known, I''d have told you*. Porteños use **hubiera** + a participle in both halves.', 'draft'),
  ('ff92a735-5164-5693-b16f-d442465b6dbe', 'aaafb4dd-18af-5b10-be4f-33a46f2cba0e', 'The same participles', '**Hubiera** takes the participles *había* does: **sabido, venido, ido, llamado, dicho, hecho**. **Si hubieras venido** — *if you had come*.', 'draft'),
  ('4cb250cf-f227-501f-aefc-fb7775e2e1ca', '9cd92c11-142e-5820-ac05-2ba0eb3f623c', 'Por un lado, por otro lado', '**Por un lado… por otro lado** weighs two sides. **En cambio** — *whereas* — sets two people or things against each other: *yo laburo, en cambio él no*.', 'draft'),
  ('b2d04c3b-a80f-5173-ba94-693c40ae1e39', '9cd92c11-142e-5820-ac05-2ba0eb3f623c', 'De hecho, en realidad', '**De hecho** — *in fact* — backs up what you just said. **En realidad** — *actually* — corrects it: *en realidad no es tan caro*. **Por eso** — *that''s why*.', 'draft'),
  ('96bfd871-c811-5edf-8fe3-6f07c3c37007', '53eebe4b-3a77-563a-84b1-b0ae2a42641c', 'Sacar turno', 'For almost anything official you first **sacás turno** — you book an appointment online — and you bring the **DNI**, the national ID card, without which nothing happens.', 'draft'),
  ('69d02752-e744-5eaf-b2d3-5ee433c31092', '53eebe4b-3a77-563a-84b1-b0ae2a42641c', 'Vencido', 'A document that has run out is **vencido**: *tengo el pasaporte vencido*. You **renovás** it, fill in a **formulario**, wait in the **fila**, and **firmás**.', 'draft'),
  ('502bcb85-b4a1-5f05-8424-865eee3938da', '29bb2939-3d2a-50ef-b526-0e4e6c65ed68', 'Hubiera + participle', '**Si hubiera sabido, te hubiera avisado** — both halves take **hubiera**, for something that didn''t happen.', 'draft'),
  ('946fc56a-0082-512d-b30a-4261c6453307', '29bb2939-3d2a-50ef-b526-0e4e6c65ed68', 'En cambio, de hecho', '**En cambio** sets two things against each other; **de hecho** backs up what you said; **en realidad** corrects it.', 'draft'),
  ('26cd1c59-3bde-5419-a671-c284d50d45ef', '3a4f3640-2502-5b70-b610-aa933a78c1a5', 'Arguing like a porteño', 'An argument in Buenos Aires is a sport, not a fight: **discutimos** a lot and stay friends. **Me convenciste** — *you''ve convinced me*; **cambié de idea** — *I changed my mind*.', 'draft'),
  ('b7afb44a-1c0b-5fec-b131-4baa591997be', '3a4f3640-2502-5b70-b610-aa933a78c1a5', '¡Ojo!', '**¡Ojo!** — literally *eye!* — is *careful!, watch out!*: **ojo, que no es tan fácil**. **Estoy seguro** — *I''m sure*; **no estoy segura** — *I''m not sure*.', 'draft')
